css:
.print-format .fk-td { font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif; color: #111827; font-size: 9.5pt; line-height: 1.4;
	-webkit-print-color-adjust: exact; print-color-adjust: exact; }
.print-format .fk-td-head { width: 100%; border-collapse: collapse; border-bottom: 2px solid #111827; margin-bottom: 14pt; }
.print-format .fk-td-head > tbody > tr > td { vertical-align: top; padding: 0 0 12pt; }
.print-format .fk-td-head-facts { text-align: right; }
.print-format .fk-td-head-facts .fk-td-facts { margin-left: auto; }
.print-format .fk-td-kicker { font-size: 8pt; font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; color: #6b7280; }
.print-format .fk-td-title { font-size: 22pt; font-weight: 800; margin: 2pt 0 2pt; line-height: 1.15; }
.print-format .fk-td-ref { color: #6b7280; font-size: 10pt; }
.print-format .fk-td-facts { border-collapse: collapse; font-size: 9pt; }
.print-format .fk-td-facts th { text-align: left; font-weight: 400; color: #6b7280; padding: 2pt 12pt 2pt 0; white-space: nowrap; }
.print-format .fk-td-facts td { text-align: right; font-weight: 600; padding: 2pt 0; white-space: nowrap; }
.print-format .fk-td-parties { width: 100%; border-collapse: collapse; margin-bottom: 16pt; }
.print-format .fk-td-party { width: 49%; vertical-align: top; background: #f5f6f8; border-radius: 6pt; padding: 10pt 12pt; }
.print-format .fk-td-gap { width: 2%; }
.print-format .fk-td-party-name { font-size: 11.5pt; font-weight: 700; }
.print-format .fk-td-label { font-size: 8pt; font-weight: 700; letter-spacing: 0.1em; text-transform: uppercase; color: #6b7280; margin: 0 0 5pt; }
.print-format .fk-td-label-gap { margin-top: 8pt; }
.print-format .fk-td-table { width: 100%; border-collapse: collapse; margin-bottom: 6pt; }
.print-format .fk-td-table th { font-size: 8pt; font-weight: 600; text-transform: uppercase; letter-spacing: 0.04em; color: #6b7280;
	text-align: left; padding: 6pt 6pt; border-bottom: 1.5px solid #111827; }
.print-format .fk-td-table td { padding: 5pt 6pt; border-bottom: 1px solid #e5e7eb; vertical-align: top; }
.print-format .fk-td-table .r { text-align: right; white-space: nowrap; font-variant-numeric: tabular-nums; }
.print-format .fk-td-table tfoot td { font-weight: 800; font-size: 10.5pt; border-top: 1.5px solid #111827; border-bottom: 3px double #111827; padding: 7pt 6pt; }
.print-format .fk-td-num-col, .print-format .fk-td-ref-col { width: 26pt; color: #6b7280; }
.print-format .fk-td-words { font-style: italic; color: #374151; margin: 4pt 0 16pt; }
.print-format .fk-td-notes { margin-bottom: 14pt; }
.print-format .fk-td-muted { color: #6b7280; }
.print-format .fk-td-small { font-size: 8.5pt; }
.print-format .fk-td-bill-head { width: 100%; border-collapse: collapse; border-bottom: 2px solid #111827; margin-bottom: 8pt; }
.print-format .fk-td-bill-head > tbody > tr > td { vertical-align: bottom; padding: 0 0 8pt; }
.print-format .fk-td-bill-head h2 { font-size: 16pt; font-weight: 800; margin: 2pt 0 0; }
.print-format .fk-td-bill-units { color: #6b7280; text-align: right; white-space: nowrap; }
.print-format .fk-td-bill-units span { font-size: 16pt; font-weight: 800; color: #111827; }
.print-format .fk-td-lines td { font-size: 9pt; }
.print-format .fk-td-section { page-break-inside: avoid; }
.print-format .fk-td-section-head td { background: #f1f3f6; font-weight: 700; font-size: 9.5pt; border-bottom: 1px solid #d1d5db; }
.print-format .fk-td-section-total td { font-weight: 700; background: #fafafa; border-bottom: 1px solid #d1d5db; }
.print-format .fk-td-accept { page-break-inside: avoid; margin-top: 22pt; padding-top: 12pt; border-top: 1px solid #e5e7eb; }
.print-format .fk-td-signs { width: 100%; border-collapse: collapse; margin-top: 30pt; }
.print-format .fk-td-sign { width: 49%; vertical-align: top; font-size: 9pt; }
.print-format .fk-td-line { border-bottom: 1px solid #111827; height: 26pt; margin-bottom: 4pt; }
.print-format .fk-td thead { display: table-header-group; }
.print-format .fk-td-footer { width: 100%; border-collapse: collapse; border-top: 1px solid #d1d5db; font-family: Inter, system-ui, -apple-system, "Segoe UI", sans-serif;
	font-size: 7.5pt; line-height: 1.45; color: #6b7280; }
.print-format .fk-td-footer td { vertical-align: top; padding: 5pt 0 0; }
.print-format .fk-td-footer-company { font-weight: 700; color: #111827; }
.print-format .fk-td-footer-page { text-align: right; white-space: nowrap; }
.print-format .fk-td-footer-pages { border-top: 0; }
.print-format .letter-head { margin-bottom: 14pt; }
.print-format .fk-td-footer-note { font-style: italic; color: #9ca3af; }
